import { initializeApp } from 'firebase/app';
import { getAuth, signInWithEmailAndPassword } from 'firebase/auth';
import { getFirestore, addDoc, collection, serverTimestamp } from 'firebase/firestore';

// Paste your Firebase config here
const firebaseConfig = {
  apiKey: 'YOUR_API_KEY',
  authDomain: 'YOUR_AUTH_DOMAIN',
  projectId: 'YOUR_PROJECT_ID',
  storageBucket: 'YOUR_STORAGE_BUCKET',
  messagingSenderId: 'YOUR_SENDER_ID',
  appId: 'YOUR_APP_ID'
};

const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);

async function loginUser() {
  const email = prompt('Enter your email:');
  const password = prompt('Enter your password:');
  try {
    await signInWithEmailAndPassword(auth, email, password);
    alert('✅ Login successful!');
  } catch (e) {
    alert('❌ Login failed: ' + e.message);
  }
}

// Auto-trigger login on page load
window.onload = () => {
  loginUser();
};

const recognition = new (window.SpeechRecognition || window.webkitSpeechRecognition)();
recognition.lang = 'kn-IN';

recognition.onstart = () => { showListening(true); };
recognition.onend = () => { showListening(false); };
recognition.onresult = async (event) => {
  const transcript = event.results[0][0].transcript;
  addMessage('user', transcript);
  await sendToAI(transcript);
};

function speak(text) {
  const utter = new SpeechSynthesisUtterance(text);
  utter.lang = /[\u0C80-\u0CFF]/.test(text) ? 'kn-IN' : 'en-IN';
  speechSynthesis.speak(utter);
}

function showListening(state) {
  const mic = document.getElementById('mic-status');
  if (mic) mic.innerText = state ? '🎙️ Listening…' : '🎤 Tap to speak';
}

function showThinking(state) {
  const status = document.getElementById('ai-status');
  if (status) status.innerText = state ? '🤔 Sada is thinking…' : '';
}

function addMessage(role, text) {
  const chat = document.getElementById('chat');
  const msg = document.createElement('div');
  msg.className = role;
  msg.textContent = text;
  chat.appendChild(msg);
  chat.scrollTop = chat.scrollHeight;
}

async function sendToAI(userText) {
  showThinking(true);
  try {
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${process.env.OpenAI}`
      },
      body: JSON.stringify({
        model: 'gpt-4o',
        messages: [
          { role: 'system', content: 'You are SADA, an empathetic agricultural assistant for Indian farmers. Speak in clear, kind, bilingual Kannada and English, providing farming, weather, crop, and scheme help naturally.' },
          { role: 'user', content: userText }
        ]
      })
    });

    const data = await response.json();
    const reply = data.choices?.[0]?.message?.content || '⚠️ No response from AI.';
    addMessage('ai', reply);
    speak(reply);

    await addDoc(collection(db, 'chats'), {
      user: userText,
      ai: reply,
      time: serverTimestamp()
    });
  } catch (e) {
    addMessage('ai', '⚠️ Sorry, I’m having trouble right now.');
  } finally {
    showThinking(false);
  }
}
